import{_ as i,o as a,c as r,a2 as e}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"釀酒基礎教學","description":"釀酒插件的基礎教學，成為頂尖釀酒師的起點。","frontmatter":{"title":"釀酒基礎教學","description":"釀酒插件的基礎教學，成為頂尖釀酒師的起點。"},"headers":[],"relativePath":"feature/brewery/info/index.md","filePath":"feature/brewery/info.md"}'),t={name:"feature/brewery/info/index.md"};function o(h,l,n,s,c,d){return a(),r("div",null,[...l[0]||(l[0]=[e('<h1 id="基礎教學" tabindex="-1">基礎教學 <a class="header-anchor" href="#基礎教學" aria-label="Permalink to &quot;基礎教學&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">公告</p><p>生存分流已於2025/06/08隨版本更新關閉釀酒功能，目前沒有可以釀酒的分流</p></div><div class="tip custom-block"><p class="custom-block-title">警語</p><p>未成年請勿飲酒。喝酒不開車，開車不喝酒。</p></div><h2 id="基本的釀造方法" tabindex="-1">基本的釀造方法 <a class="header-anchor" href="#基本的釀造方法" aria-label="Permalink to &quot;基本的釀造方法&quot;">​</a></h2><ul><li><p>首先 你需要一個 <strong>釀酒鍋</strong></p></li><li><p>釀酒鍋製造方法：一個鍋釜裝水 並在下方擺上營火<br><img src="https://i.imgur.com/w3nqzxJ.png" style="height:20%;width:20%;"></p></li></ul><ol><li>裝一桶水倒進鍋裡</li><li>手持原料 <strong>並右鍵鍋子</strong> 即可加入鍋裡<br> (右鍵1次會加入1個原料 要自己記得加了哪些原料跟數量)<br> 並開始等待</li><li>等待時間可手持時鐘右鍵 查看烹煮時間</li><li>當你覺得時間OK了 用3個空玻璃瓶撈起來 會獲得半成品/成品</li><li>接著依照酒類需求 決定是否繼續 蒸餾或貯存</li></ol><h2 id="蒸餾" tabindex="-1">蒸餾 <a class="header-anchor" href="#蒸餾" aria-label="Permalink to &quot;蒸餾&quot;">​</a></h2><p>許多酒類煮完後只會得到半成品<br> 需要進行蒸餾繼續加工</p><h3 id="蒸餾台製造方法" tabindex="-1">蒸餾台製造方法 <a class="header-anchor" href="#蒸餾台製造方法" aria-label="Permalink to &quot;蒸餾台製造方法&quot;">​</a></h3><p>釀造台 裡面放一個螢光粉<br> (螢光粉不會被消耗)<br><img src="https://i.imgur.com/6SQK8cL.png" style="width:60%;"></p><h3 id="蒸餾次數" tabindex="-1">蒸餾次數 <a class="header-anchor" href="#蒸餾次數" aria-label="Permalink to &quot;蒸餾次數&quot;">​</a></h3><p>當釀造台次數跑完1次<br> 代表已完成蒸餾了1次(飲品上會寫)<br> 不同的酒有不同的蒸餾次數</p><h2 id="貯存" tabindex="-1">貯存 <a class="header-anchor" href="#貯存" aria-label="Permalink to &quot;貯存&quot;">​</a></h2><p>有些酒可以儲藏起來繼續加工<br> 此時你需要建造酒桶來放</p><h3 id="存放木桶" tabindex="-1">存放木桶 <a class="header-anchor" href="#存放木桶" aria-label="Permalink to &quot;存放木桶&quot;">​</a></h3><ul><li>製造方法：酒桶 長4寬3高4</li><li>建材 : 木材x18，木樓梯x16，木柵欄x5</li><li>在前方貼一個木牌寫上Barrel<br> 並提示貯藏桶創建成功才可用。<br> (有不同木種的存放木桶，各個都有不同的酒類能存放)<br><img src="https://i.imgur.com/Rh0wHrc.png" style="width:70%;"></li></ul><h3 id="貯存時間" tabindex="-1">貯存時間 <a class="header-anchor" href="#貯存時間" aria-label="Permalink to &quot;貯存時間&quot;">​</a></h3><ul><li>遊戲時間1天=酒放了1年</li><li>酒不是越放越久越好</li></ul><h2 id="釀造相關知識" tabindex="-1">釀造相關知識 <a class="header-anchor" href="#釀造相關知識" aria-label="Permalink to &quot;釀造相關知識&quot;">​</a></h2><ul><li>飲品有品質高低，所加入的材料以及燉煮的時間會影響成品的品質，<br> 同時也決定飲品是否成功。</li><li>釀造參數，包含 <ul><li>材料數量</li><li>燉煮時間</li><li>蒸餾次數</li><li>貯存木桶種類</li><li>貯存年份</li></ul></li><li>將飲品放入釀造台可以得知那項飲品的酒精濃度，<br> 把飲品放入存放木桶一小段時間則可以看其品質。</li><li>每種酒都有屬於他最完美的參數<br> 酒譜只會給出範圍，參數越靠近該值，酒的品質越高(影響飲品的效果強度)</li><li>難度(1-10) 為酒能接受的精準度<br> 難度越高的酒 參數與精準值差異越大 則越容易失敗</li></ul><h2 id="酒醉" tabindex="-1">酒醉 <a class="header-anchor" href="#酒醉" aria-label="Permalink to &quot;酒醉&quot;">​</a></h2><ul><li>喝下酒之後會酒醉，走路也會搖搖晃晃，可喝東西或吃東西來解酒 <ul><li>酒醉效果會跨分流</li></ul></li><li><code>/brew info</code>查看自身酒醉程度。</li><li>解酒物品 <ul><li>麵包 -2</li><li>牛奶桶 -5</li><li>金蘋果 -20</li></ul></li></ul><h2 id="調酒" tabindex="-1">調酒 <a class="header-anchor" href="#調酒" aria-label="Permalink to &quot;調酒&quot;">​</a></h2><ol><li>將調酒需要的材料 放入鍋中 煮2分鐘後取出 此為調酒成品</li><li>取出的調酒基底 放入蒸餾器蒸餾一次 即可完成</li><li>通常使用不好又不差的酒</li></ol><h2 id="釀造配方" tabindex="-1">釀造配方 <a class="header-anchor" href="#釀造配方" aria-label="Permalink to &quot;釀造配方&quot;">​</a></h2><ul><li>這邊只會給釀造的變數範圍<br> 最完美的值請自行摸索出來</li><li>沒有寫蒸餾 代表該飲品不需要蒸餾</li><li>沒有寫貯存 代表該飲品不需要貯存放木桶</li><li>要貯存的酒一定會跟你說要貯存<br> 但不會給你年份範圍</li></ul><h2 id="特殊材料" tabindex="-1">特殊材料 <a class="header-anchor" href="#特殊材料" aria-label="Permalink to &quot;特殊材料&quot;">​</a></h2><ul><li>有些酒需要使用特殊材料</li><li>調酒產生的特殊材料 會以 <em>斜體</em> 表示</li><li>酒 會以 <strong>粗體</strong> 表示</li><li>由副本入手的材料 會在材料前加一個#</li></ul><h2 id="密封" tabindex="-1">密封 <a class="header-anchor" href="#密封" aria-label="Permalink to &quot;密封&quot;">​</a></h2><p>酒在製成之後，可以將其密封，密封完成的酒將無法繼續貯存年份與蒸餾<br> 也不能查看其年份、材料、蒸餾次數(只會顯示幾星)</p><p>在你製作好酒之後很適合密封起來放/賣給別人</p><ol><li>首先 需要合成一個密封槽 (外觀是煙燻爐)<br> 木材(任意種類)x4+空瓶子x2<br><img src="https://i.imgur.com/5hwWXeM.png" style="width:70%;"></li><li>將其放置在地上<br> 右鍵點開 將要密封的酒<br> 放在九宮格上任意位置</li><li>等待約1秒後 即完成密封 以下是密封前後<br><img src="https://i.imgur.com/5UWEwVQ.png" style="width:40%;"></li></ol>',32)])])}const p=i(t,[["render",o]]);export{b as __pageData,p as default};
